1	// Backend tests for reverse IncidentLog -> DetectionAlert synchronisation on
2	// /api/incident — the mirror image of detectionAlerts.js's forward sync (tested in
3	// detection-alerts.test.js). Editing/deleting an incident from the Incident Dashboard
4	// must keep the linked Object Detection alert consistent, in one transaction.
5	const request = require("supertest");
6	const express = require("express");
7	const jwt = require("jsonwebtoken");
8	
9	process.env.APP_SECRET = "test-secret";
10	
11	const mockIncidentLog = {
12	  findAll: jest.fn(),
13	  findByPk: jest.fn(),
14	  create: jest.fn(),
15	};
16	const mockDetectionAlert = {
17	  findOne: jest.fn(),
18	};
19	const mockTx = { id: "tx" };
20	const mockSequelize = { transaction: jest.fn(async (fn) => fn(mockTx)) };
21	
22	jest.mock("../../models", () => ({
23	  IncidentLog: mockIncidentLog,
24	  DetectionAlert: mockDetectionAlert,
25	  sequelize: mockSequelize,
26	}));
27	
28	const incidentRouter = require("../../routes/incident");
29	
30	const app = express();
31	app.use(express.json());
32	app.use("/api/incident", incidentRouter);
33	
34	const fmToken = jwt.sign({ id: 1, role: "FM" }, process.env.APP_SECRET);
35	
36	const makeIncidentInstance = (overrides = {}) => ({
37	  id: 1,
38	  resolutionStatus: "Active",
39	  severity: "Medium",
40	  person_name: null,
41	  notes: "",
42	  update: jest.fn().mockResolvedValue(),
43	  destroy: jest.fn().mockResolvedValue(),
44	  ...overrides,
45	});
46	
47	const makeAlertInstance = (overrides = {}) => ({
48	  id: 9,
49	  incident_log_id: 1,
50	  status: "Active",
51	  update: jest.fn().mockResolvedValue(),
52	  destroy: jest.fn().mockResolvedValue(),
53	  ...overrides,
54	});
55	
56	describe("PATCH /api/incident/:id — reverse sync to DetectionAlert", () => {
57	  beforeEach(() => jest.clearAllMocks());
58	
59	  test("resolutionStatus update mirrors onto the linked alert's status", async () => {
60	    const incident = makeIncidentInstance();
61	    const alert = makeAlertInstance();
62	    mockIncidentLog.findByPk.mockResolvedValue(incident);
63	    mockDetectionAlert.findOne.mockResolvedValue(alert);
64	
65	    const res = await request(app)
66	      .patch("/api/incident/1")
67	      .set("Authorization", `Bearer ${fmToken}`)
68	      .send({ resolutionStatus: "Escalated to Security" });
69	
70	    expect(res.status).toBe(200);
71	    expect(mockDetectionAlert.findOne).toHaveBeenCalledWith(expect.objectContaining({
72	      where: { incident_log_id: 1 },
73	    }));
74	    expect(alert.update).toHaveBeenCalledWith({ status: "Escalated" }, { transaction: mockTx });
75	    expect(mockSequelize.transaction).toHaveBeenCalledTimes(1);
76	  });
77	
78	  test("Cleared resolutionStatus maps to the alert's Cleared status", async () => {
79	    const incident = makeIncidentInstance();
80	    const alert = makeAlertInstance();
81	    mockIncidentLog.findByPk.mockResolvedValue(incident);
82	    mockDetectionAlert.findOne.mockResolvedValue(alert);
83	
